Send Referral to proGres.code:
// Send an interagency referral into proGres v4 via DTP.
postData({
  // DTP endpoint from the credential; DTP routes on request_type.
  url: $.configuration.url,
  body: {
    request_type: 'ReceiveIncomingReferral',
    // Unique per case/service pair.
    id: $.data.referralId,
    service_implementing_agency: 'UNHCR',
    owned_by_agency_id: 'UNICEF',
    service_type: 'Child Protection Service',
    service_response_day_time: $.data.serviceDueAt,
    service_referral_notes: 'Interoperability referral',
    primero_user: $.data.caseworkerUsername,
    full_name: 'CP Worker',
    unhcr_individual_no: $.data.unhcrIndividualNo,
    unhcr_id_no: $.data.unhcrIdNo,
    name_first: 'Given',
    name_last: 'Family',
    date_of_birth: '2012-05-04',
    sex: 'female',
    language: 'English',
    risk_level: 'High',
  },
  headers: {
    // DTP subscription key.
    'Ocp-Apim-Subscription-Key': $.configuration.token,
  },
  // Client certificate for mutual TLS.
  agentOptions: {
    key: $.configuration.key,
    cert: $.configuration.cert,
  },
});

Report Referral Decision.code:
// Report the decision on a referral proGres sent out.
postData({
  url: $.configuration.url,
  body: {
    request_type: 'ReceiveDecisionOutgoingReferral',
    case_id: $.data.caseId,
    primero_user: $.data.caseworkerUsername,
    // proGres intervention number, e.g. NAI-20-PRTITV-0000006.
    progres_interventionnumber: $.data.interventionNumber,
    // e.g. 'acknowledged' or 'rejected'.
    status: $.data.status,
    closure_reason: $.data.reason,
  },
  headers: { 'Ocp-Apim-Subscription-Key': $.configuration.token },
  agentOptions: { key: $.configuration.key, cert: $.configuration.cert },
});

Send Delivery Feedback.code:
// Report that an intervention could not be created.
postData({
  url: $.configuration.url,
  body: {
    request_type: 'Feedback',
    case_id: $.data.caseId,
    primero_user: $.data.caseworkerUsername,
    progres_interventionnumber: $.data.interventionNumber,
    // 'Pending Acknowledgement' on success, 'Delivery Fail' on failure.
    status: 'Delivery Fail',
    closure_reason: 'Referral is missing required fields. Please complete and re-send.',
  },
  headers: { 'Ocp-Apim-Subscription-Key': $.configuration.token },
  agentOptions: { key: $.configuration.key, cert: $.configuration.cert },
});
